-- single IS entry, Atlantic/Reykjavik (read on this machine 2026-10-30).
values ('IS', 'Iceland', '🇮🇸', array['Atlantic/Reykjavik'])
on conflict (country_code) do nothing;

on conflict (country_code, name, coalesce(region, '')) do nothing;

commit;
